% Given data
t = [0 1 2 3 4];
k = [0.10 0.25 0.35 0.40 0.42];

% Composite trapezoidal integration
dt = t(2) - t(1);

% Composite trapezoidal rule
I_trap = dt/2 * (k(1) + ...
    2*sum(k(2:end-1)) + k(end));

% Heat transferred using Part (b)
Qk = 482.7;
H = Qk * I_trap;

% Display results
fprintf('Trapezoidal integral = %.6f\n', I_trap); %[output:9f94c558]
fprintf('Heat transferred = %.3f J\n', H); %[output:5abec3ba]

% Verify with MATLAB built-in function
I_builtin = trapz(t, k);
fprintf('MATLAB trapz = %.6f\n', I_builtin); %[output:1687f9ef]



% Plot the four trapezoidal areas
figure('Color', 'w'); %[output:87b6921a]
hold on; %[output:87b6921a]
for i = 1:length(t)-1
    x = [t(i), t(i+1), t(i+1), t(i)];
    y = [0, 0, k(i+1), k(i)];

    patch(x, y, [0.65 0.82 1.0], ... %[output:87b6921a]
        'FaceAlpha', 0.4, ... %[output:87b6921a]
        'EdgeColor', 'k', ... %[output:87b6921a]
        'LineWidth', 0.8, ... %[output:87b6921a]
        'HandleVisibility', 'off'); %[output:87b6921a]
end

% Plot piecewise-linear approximation
plot(t, k, 'b-', ... %[output:87b6921a]
    'LineWidth', 2, ... %[output:87b6921a]
    'DisplayName', 'Linear interpolation'); %[output:87b6921a]

% Plot given data points
plot(t, k, 'ro', ... %[output:87b6921a]
    'MarkerFaceColor', 'r', ... %[output:87b6921a]
    'MarkerSize', 7, ... %[output:87b6921a]
    'DisplayName', 'Given data'); %[output:87b6921a]

% Formatting
xlabel('t (s)', 'FontSize', 12); %[output:87b6921a]
ylabel('k (W/(m K))', ... %[output:87b6921a]
    'FontSize', 12); %[output:87b6921a]

title(sprintf('Composite Trapezoidal Rule (I = %.4f)', I)); %[output:87b6921a]

legend('Location', 'southeast'); %[output:87b6921a]
grid on; %[output:87b6921a]
box on; %[output:87b6921a]

xlim([0 4]); %[output:87b6921a]
ylim([0 0.5]); %[output:87b6921a]
xticks(0:1:4); %[output:87b6921a]

set(gca, 'FontSize', 11); %[output:87b6921a]

% Export as vector PDF for Overleaf
exportgraphics(gcf, 'trapez.pdf', ... %[output:group:61beebbb] %[output:87b6921a]
    'ContentType', 'vector'); %[output:group:61beebbb] %[output:87b6921a]

